#include <string>
#include <cmath>

using namespace std;

class Solution {
public:
    string smallestGoodBase(string n) {
        long long N = stoll(n);
        for (int m = log2(N); m >= 1; --m) {
            long long k = pow(N, 1.0 / m);
            long long sum = 1, curr = 1;
            for (int i = 0; i < m; ++i)
                sum = sum * k + 1;
            if (sum == N) return to_string(k);
        }
        return to_string(N - 1);
    }
};
